				{ id: "openai/gpt-5", expected: ModelFamily.NEXT_GEN },
				{ id: "gemini3", provider: "vertex", expected: ModelFamily.GEMINI_3, useNativeTools: true },
				{ id: "unknown-model", expected: ModelFamily.GENERIC },
			]

			for (const { id, expected, provider, useNativeTools } of testCases) {
				const providerId = provider ?? "random"
				const customPrompt = provider === "lmstudio" ? "compact" : undefined
				const providerInfo = { ...mockProviderInfo, providerId, model: { ...mockProviderInfo.model, id }, customPrompt }
				const result = registry.getModelFamily({
					...mockContext,
					providerInfo,
					enableNativeToolCalls: useNativeTools ?? false,
				})
				expect(result).to.equal(expected, `Failed for model ${id} with provider ${providerId}`)
			}
		})
	})

	describe("get method", () => {
		it("should handle fallback to generic variant", async () => {
			try {
				// Try to get a prompt for an unknown model
				// This should fallback to generic or throw an appropriate error
				const prompt = await registry.get(mockContext)

				// If we get a prompt, it should be a string
				expect(prompt).to.be.a("string")
				if (prompt.length > 0) {
					expect(prompt.length).to.be.greaterThan(10)
				}
			} catch (error) {
				// It's okay if it throws an error about missing variants
				expect(error).to.be.instanceOf(Error)
			}
		})
	})

	describe("native tools", () => {
		it("should not include focus_chain in native tools output", async () => {
			const nativeContext: SystemPromptContext = {
				...mockContext,
				enableNativeToolCalls: true,
				providerInfo: {
					...mockProviderInfo,
					providerId: "openai-native",
					model: { ...mockProviderInfo.model, id: "gpt-5" },
				},
			}

			await registry.get(nativeContext)
			const nativeTools = registry.nativeTools

			expect(nativeTools).to.be.an("array").that.is.not.empty

			// OpenAI-native tools are function tools; keep a fallback for other providers.
			const toolNames = (nativeTools as any[]).map((tool) => {
				if (tool?.type === "function") {
					return tool.function?.name
				}
				return tool?.name
			})

			expect(toolNames).to.not.include("focus_chain")
			expect(JSON.stringify(nativeTools)).to.not.include('"focus_chain"')
		})
	})

	describe("getAvailableModels", () => {
		it("should return list of available model IDs", () => {
			const models = registry.getAvailableModels()
			expect(models).to.be.an("array")
			// Should be empty initially since no variants are loaded
			expect(models.length).to.be.greaterThanOrEqual(0)
		})
	})

	describe("registerComponent", () => {
		it("should register custom components", () => {
			const mockComponent = async () => "CUSTOM COMPONENT"

			registry.registerComponent("custom", mockComponent)

			expect((registry as any).components.custom).to.equal(mockComponent)
		})
	})

	describe("basic functionality", () => {
		it("should be able to create registry instance", () => {
			expect(registry).to.be.instanceOf(PromptRegistry)
		})

		it("should have required methods", () => {
			expect(registry.get).to.be.a("function")
			expect(registry.getVersion).to.be.a("function")
			expect(registry.getByTag).to.be.a("function")
			expect(registry.registerComponent).to.be.a("function")
			expect(registry.getAvailableModels).to.be.a("function")
		})
	})
})

import { expect } from "chai"
import type { McpHub } from "@/services/mcp/McpHub"
import { TemplateEngine } from "../templates/TemplateEngine"
import type { SystemPromptContext } from "../types"
import { mockProviderInfo } from "./integration.test"

describe("TemplateEngine", () => {
	let templateEngine: TemplateEngine

	beforeEach(() => {
		templateEngine = new TemplateEngine()
	})

	describe("resolve", () => {
		const mockContext: SystemPromptContext = {
			cwd: "/test/project",
			ide: "TestIde",
			supportsBrowserUse: true,
			mcpHub: {
				getServers: () => [],
				getMcpServersPath: () => "/test/mcp-servers",
				getSettingsDirectoryPath: () => "/test/settings",
				clientVersion: "1.0.0",
				disposables: [],
			} as unknown as McpHub,
			focusChainSettings: {
				enabled: true,
				remindClineInterval: 6,
			},
			browserSettings: {
				viewport: {
					width: 1280,
					height: 720,
				},
			},
			isTesting: true,
			providerInfo: mockProviderInfo,
			yoloModeToggled: false,
		}

		it("should resolve simple placeholders", () => {
			const template = "Hello {{name}}!"
			const placeholders = { name: "World" }
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal("Hello World!")
		})

		it("should resolve multiple placeholders", () => {
			const template = "{{greeting}} {{name}}, today is {{day}}"
			const placeholders = {
				greeting: "Hello",
				name: "Alice",
				day: "Monday",
			}
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal("Hello Alice, today is Monday")
		})

		it("should handle nested object placeholders", () => {
			const template = "User: {{user.name}}, Age: {{user.age}}"
			const placeholders = {
				user: {
					name: "John",
					age: 30,
				},
			}
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal("User: John, Age: 30")
		})

		it("should preserve unmatched placeholders", () => {
			const template = "Hello {{name}}, your {{missing}} is pending"
			const placeholders = { name: "Alice" }
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal("Hello Alice, your {{missing}} is pending")
		})

		it("should handle object and array values", () => {
			const template = "Config: {{config}}"
			const placeholders = {
				config: { key: "value", items: [1, 2, 3] },
			}
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal('Config: {"key":"value","items":[1,2,3]}')
		})

		it("should handle whitespace around placeholder names", () => {
			const template = "Hello {{ name }}, welcome to {{  place  }}"
			const placeholders = { name: "Bob", place: "Paradise" }
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal("Hello Bob, welcome to Paradise")
		})
	})

	describe("extractPlaceholders", () => {
		it("should extract all unique placeholders", () => {
			const template = "Hello {{name}}, {{greeting}} {{name}}!"
			const placeholders = templateEngine.extractPlaceholders(template)
			expect(placeholders).to.deep.equal(["name", "greeting"])
		})

		it("should handle nested placeholders", () => {
			const template = "User {{user.name}} lives in {{user.location.city}}"
			const placeholders = templateEngine.extractPlaceholders(template)
			expect(placeholders).to.deep.equal(["user.name", "user.location.city"])
		})

		it("should handle whitespace in placeholders", () => {
			const template = "Hello {{  name  }} and {{greeting}}"
			const placeholders = templateEngine.extractPlaceholders(template)
			expect(placeholders).to.deep.equal(["name", "greeting"])
		})

		it("should return empty array for template without placeholders", () => {
			const template = "Hello World!"
			const placeholders = templateEngine.extractPlaceholders(template)
			expect(placeholders).to.deep.equal([])
		})
	})

	describe("validate", () => {
		it("should return missing placeholders", () => {
			const template = "Hello {{name}}, your order is ready"
			const required = ["name", "missing"]
			const missing = templateEngine.validate(template, required)
			expect(missing).to.deep.equal(["missing"])
		})

		it("should return empty array when all required placeholders are present", () => {
			const template = "Hello {{name}}, your {{item}} is ready"
			const required = ["name", "item"]
			const missing = templateEngine.validate(template, required)
			expect(missing).to.deep.equal([])
		})
	})

	describe("escape and unescape", () => {
		it("should escape placeholder markers", () => {
			const template = "Hello {{name}}!"
			const escaped = templateEngine.escape(template)
			expect(escaped).to.equal("Hello \\{\\{name\\}\\}!")
		})

		it("should unescape placeholder markers", () => {
			const escaped = "Hello \\{\\{name\\}\\}!"
			const unescaped = templateEngine.unescape(escaped)
			expect(unescaped).to.equal("Hello {{name}}!")
		})

		it("should handle round-trip escaping/unescaping", () => {
			const template = "Hello {{name}}! Welcome to {{place}}."
			const escaped = templateEngine.escape(template)
			const unescaped = templateEngine.unescape(escaped)
			expect(unescaped).to.equal(template)
		})
	})
})

